import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> {
  List<NewsModel> _news = const [];

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = Tween<double>(begin: 0.25, end: 1).animate(_scaleController);
  }

  void _initData() {
    final newsRepository = context.read<NewsRepository>();

    // 1. Мгновенно показываем кэш (только БД).
    newsRepository.loadNewsFeed(const NewsFeedFilter.all).then((List<NewsModel> cached) {
      if (!mounted) return;
      setState(() => _news = cached);
    });

    // 2. Параллельно — фоновая загрузка из сети с записью в кэш.
    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> fresh) {
      if (!mounted) return;
      setState(() => _news = fresh);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ScaleTransition(
        scale: _scaleAnimation,
        child: ListView.builder(
            itemCount: _news.length,
            itemBuilder: (BuildContext context, int index) {
              final NewsModel news = _news[index];

              return Padding(
                key: ValueKey(news.link),
                padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                child: NewsCard(model: news),
              );
            },
            padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
          ),
      ),
    );
  }
}

